13	/** Organization + WebSite (with site search) — rendered once in the root layout. */
14	export async function OrganizationJsonLd() {
15	  // sameAs ties "Nxeon" the brand to its social profiles in Google's entity graph —
16	  // the strongest signal for the brand knowledge panel. Read from admin settings so
17	  // it stays in sync with the marketing footer; only real http(s) URLs are included.
18	  let sameAs: string[] = [];
19	  try {
20	    const { getSetting } = await import("@/lib/settings");
21	    const urls = await Promise.all([
22	      getSetting("social_facebook", ""),
23	      getSetting("social_instagram", ""),
24	      getSetting("social_linkedin", ""),
25	      getSetting("social_youtube", ""),
26	      getSetting("social_twitter", ""),
27	      getSetting("social_github", ""),
28	    ]);
29	    sameAs = urls.map((u) => u.trim()).filter((u) => /^https?:\/\//i.test(u));
30	  } catch {
31	    /* settings unavailable — emit an empty sameAs rather than fail the layout */
32	  }
33	  return (
34	    <>
35	      <JsonLd
36	        data={{
37	          "@context": "https://schema.org",
38	          "@type": "Organization",
39	          name: "Nxeon",
40	          url: APP_URL,
41	          // A raster logo (min 112x112) is what Google uses for the brand/knowledge
