60	export function formatDate(d: Date | string | null | undefined): string {
61	  if (!d) return "";
62	  const date = typeof d === "string" ? new Date(d) : d;
63	  return date.toLocaleDateString("en-US", { year: "numeric", month: "long", day: "numeric" });
