72	/* ----------------------------------------------------------------------------
73	 * Tiny, self-contained markdown → HTML renderer.
74	 *
75	 * No external dependency. Handles: # / ## / ### headings, **bold**, `code`,
76	 * fenced ``` code blocks, - / * and 1. lists, [links](url), and blank-line
77	 * separated paragraphs. HTML is escaped BEFORE any markdown is applied, and
78	 * inline code spans are protected so their contents are never re-processed.
79	 * Output carries Tailwind classes so it reads well on the dark theme (there is
80	 * no typography plugin installed).
81	 * ------------------------------------------------------------------------- */
82	
83	function esc(s: string): string {
84	  return s
85	    .replace(/&/g, "&amp;")
86	    .replace(/</g, "&lt;")
87	    .replace(/>/g, "&gt;");
88	}
