90	const CLS = {
91	  h1: "mt-10 mb-4 text-3xl font-bold tracking-tight text-white",
92	  h2: "mt-10 mb-3 text-2xl font-bold tracking-tight text-white",
93	  h3: "mt-8 mb-2 text-xl font-semibold text-white",
94	  p: "mb-4 leading-relaxed text-slate-300",
95	  ul: "mb-5 list-disc space-y-1.5 pl-6 text-slate-300 marker:text-brand-400",
96	  ol: "mb-5 list-decimal space-y-1.5 pl-6 text-slate-300 marker:text-brand-400",
97	  li: "leading-relaxed",
98	  a: "text-brand-300 underline decoration-brand-300/40 underline-offset-2 hover:text-brand-200",
99	  code: "rounded-md border border-white/10 bg-white/[0.06] px-1.5 py-0.5 font-mono text-[0.85em] text-brand-200",
100	  pre: "mb-5 overflow-x-auto rounded-xl border border-white/10 bg-navy-950/80 p-4 font-mono text-[13px] leading-relaxed text-slate-200",
101	  img: "w-full rounded-xl border border-white/10 shadow-lg shadow-black/20",
102	};
103	
104	/** Allow only http(s) or root-relative image sources; reject everything else. */
105	function safeSrc(u: string): string {
106	  return /^(https?:\/\/|\/)/.test(u) ? u : "";
107	}
108	
109	// Private-use sentinels wrap protected inline-code indices so they can never
110	// collide with ordinary digits in prose (e.g. "2 GB", "port 25565").
111	const S0 = "";
112	const S1 = "";
113	
114	/** Inline markdown for a single run of text. */
115	function inline(text: string): string {
116	  const codes: string[] = [];
117	  // Protect inline code first.
118	  let s = esc(text).replace(/`([^`]+)`/g, (_m, c: string) => {
119	    codes.push(c);
120	    return `${S0}${codes.length - 1}${S1}`;
121	  });
122	  // Bold.
123	  s = s.replace(/\*\*([^*]+)\*\*/g, '<strong class="font-semibold text-white">$1</strong>');
124	  // Inline images ![alt](url) — MUST run before links (they share `[..](..)`).
125	  s = s.replace(/!\[([^\]]*)\]\(([^)]+)\)/g, (_m, alt: string, u: string) => {
126	    const safe = safeSrc(u);
127	    if (!safe) return "";
128	    return `<img class="${CLS.img} my-6" src="${safe}" alt="${alt}" loading="lazy" />`;
129	  });
130	  // Links [text](url) — only http(s), root-relative, or anchors are allowed.
131	  s = s.replace(/\[([^\]]+)\]\(([^)]+)\)/g, (_m, t: string, u: string) => {
132	    const safe = /^(https?:\/\/|\/|#)/.test(u) ? u : "#";
133	    const ext = safe.startsWith("http");
134	    return `<a class="${CLS.a}" href="${safe}"${ext ? ' target="_blank" rel="noopener noreferrer"' : ""}>${t}</a>`;
135	  });
136	  // Restore inline code.
137	  s = s.replace(new RegExp(`${S0}(\\d+)${S1}`, "g"), (_m, i: string) => `<code class="${CLS.code}">${codes[+i]}</code>`);
138	  return s;
139	}
140	
141	export function renderMarkdown(md: string): string {
142	  const lines = (md ?? "").replace(/\r\n/g, "\n").split("\n");
143	  const out: string[] = [];
144	  let i = 0;
145	
146	  while (i < lines.length) {
147	    const line = lines[i];
148	
149	    // Blank line — skip.
150	    if (!line.trim()) { i++; continue; }
151	
152	    // Horizontal rule.
153	    if (/^---+$/.test(line.trim())) {
154	      out.push('<hr class="my-8 border-white/[0.08]" />');
155	      i++;
156	      continue;
157	    }
158	
159	    // Standalone image line → captioned figure (not wrapped in a paragraph).
160	    const img = line.trim().match(/^!\[([^\]]*)\]\(([^)]+)\)$/);
161	    if (img) {
162	      const safe = safeSrc(img[2]);
163	      if (safe) {
164	        const alt = esc(img[1]);
165	        out.push(
166	          `<figure class="my-7"><img class="${CLS.img}" src="${safe}" alt="${alt}" loading="lazy" />` +
167	            (alt ? `<figcaption class="mt-2 text-center text-xs text-slate-500">${alt}</figcaption>` : "") +
168	            `</figure>`,
169	        );
170	        i++;
171	        continue;
172	      }
173	    }
174	
175	    // Fenced code block.
176	    if (/^```/.test(line.trim())) {
177	      const buf: string[] = [];
178	      i++;
179	      while (i < lines.length && !/^```/.test(lines[i].trim())) { buf.push(lines[i]); i++; }
180	      i++; // closing fence
181	      out.push(`<pre class="${CLS.pre}"><code>${esc(buf.join("\n"))}</code></pre>`);
182	      continue;
183	    }
184	
185	    // Headings.
186	    if (/^###\s+/.test(line)) { out.push(`<h3 class="${CLS.h3}">${inline(line.replace(/^###\s+/, ""))}</h3>`); i++; continue; }
187	    if (/^##\s+/.test(line))  { out.push(`<h2 class="${CLS.h2}">${inline(line.replace(/^##\s+/, ""))}</h2>`);  i++; continue; }
188	    if (/^#\s+/.test(line))   { out.push(`<h1 class="${CLS.h1}">${inline(line.replace(/^#\s+/, ""))}</h1>`);   i++; continue; }
189	
190	    // Ordered list.
191	    if (/^\s*\d+\.\s+/.test(line)) {
192	      const items: string[] = [];
193	      while (i < lines.length && /^\s*\d+\.\s+/.test(lines[i])) {
194	        items.push(lines[i].replace(/^\s*\d+\.\s+/, ""));
195	        i++;
196	      }
197	      out.push(`<ol class="${CLS.ol}">${items.map((t) => `<li class="${CLS.li}">${inline(t)}</li>`).join("")}</ol>`);
198	      continue;
199	    }
200	
201	    // Unordered list.
202	    if (/^\s*[-*]\s+/.test(line)) {
203	      const items: string[] = [];
204	      while (i < lines.length && /^\s*[-*]\s+/.test(lines[i])) {
205	        items.push(lines[i].replace(/^\s*[-*]\s+/, ""));
206	        i++;
207	      }
208	      out.push(`<ul class="${CLS.ul}">${items.map((t) => `<li class="${CLS.li}">${inline(t)}</li>`).join("")}</ul>`);
209	      continue;
210	    }
211	
212	    // Paragraph — gather until a blank line or block boundary.
213	    const para = [line];
214	    i++;
215	    while (
216	      i < lines.length &&
217	      lines[i].trim() &&
218	      !/^#{1,3}\s/.test(lines[i]) &&
219	      !/^\s*[-*]\s+/.test(lines[i]) &&
220	      !/^\s*\d+\.\s+/.test(lines[i]) &&
221	      !/^```/.test(lines[i].trim()) &&
222	      !/^---+$/.test(lines[i].trim())
223	    ) {
224	      para.push(lines[i]);
225	      i++;
226	    }
227	    out.push(`<p class="${CLS.p}">${inline(para.join(" "))}</p>`);
228	  }
229	
230	  return out.join("\n");
231	}
